/**
 * Independent verification of the Appendix B.1 directory-proof test vectors
 * generated by scripts/generate-directory-proof-vectors.mjs (IETF issue #120).
 *
 * This script deliberately imports NOTHING from the SDK. It re-derives every
 * value from the published bytes the way a third-party implementer would:
 *
 *   - recomputes Content-Digest from the response body
 *   - rebuilds the signature base from the covered component list parsed out of
 *     Signature-Input, in the order that list gives, rather than from any shared
 *     base-construction helper
 *   - recomputes the JWK thumbprint and uses it to select the key
 *   - verifies with node:crypto against the public key taken from the body
 *
 * Signing and verifying through the same helper only proves self-consistency.
 * This is the second path.
 *
 * Usage:
 *   node scripts/generate-directory-proof-vectors.mjs --json \
 *     | node scripts/verify-directory-proof-vectors.mjs
 *   node scripts/verify-directory-proof-vectors.mjs --from-draft <draft.txt|draft.md>
 */
import { createHash, createPublicKey, verify as nodeVerify } from 'node:crypto';
import { readFileSync } from 'node:fs';

const EXPECTED_TAG = 'http-message-signatures-directory';

const failures = [];
const check = (ok, name, detail) => {
  if (!ok) failures.push(detail ? `${name}: ${detail}` : name);
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${!ok && detail ? `\n        ${detail}` : ''}`);
};

/**
 * Undo RFC 8792 '\' line wrapping. A line ending in a backslash continues on the
 * next line, whose leading whitespace is the wrapping indent and is dropped.
 * Written to be indifferent to how far the renderer indents the block.
 */
function unfold(lines) {
  const out = [];
  for (const line of lines) {
    if (out.length && out[out.length - 1].endsWith('\\')) {
      out[out.length - 1] = out[out.length - 1].slice(0, -1) + line.trimStart();
    } else {
      out.push(line);
    }
  }
  return out;
}

/** Pull the vector out of a rendered draft (or the markdown source). */
function fromDraft(path) {
  const raw = readFileSync(path, 'utf8').split('\n').map((l) => l.replace(/\r$/, ''));
  // The heading appears twice in the .txt: once in the table of contents, once
  // for real. Take the last, so no earlier Appendix E vector can be picked up.
  const start = raw.reduce((acc, l, i) => (l.includes('Signed directory response') ? i : acc), -1);
  if (start < 0) throw new Error('section "Signed directory response" not found');
  const lines = unfold(raw.slice(start)).map((l) => l.trim());

  // A field may legitimately be printed more than once (Content-Digest appears
  // both on its own and among the response fields). Every printed copy must be
  // byte-identical: two copies that disagree is exactly the hand-editing error
  // this pass exists to catch.
  const one = (re, what) => {
    const hits = [...new Set(lines.filter((l) => re.test(l)))];
    if (hits.length === 0) throw new Error(`no ${what} found in the section`);
    if (hits.length > 1) {
      throw new Error(`${what} printed ${hits.length} different ways:\n${hits.join('\n')}`);
    }
    return hits[0];
  };

  const authorityLine = one(/^"@authority";req:/, '"@authority";req base line');
  const digestLine = one(/^Content-Digest:/, 'Content-Digest field');
  const inputLine = one(/^Signature-Input:/, 'Signature-Input field');
  const signatureLine = one(/^Signature:/, 'Signature field');
  const bodyLine = one(/^\{"keys":\[/, 'response body');
  const baseParamsLine = one(/^"@signature-params":/, '"@signature-params" base line');

  return {
    authority: authorityLine.replace(/^"@authority";req:\s*/, ''),
    body: bodyLine,
    contentDigest: digestLine.replace(/^Content-Digest:\s*/, ''),
    signatureInput: inputLine.replace(/^Signature-Input:\s*/, ''),
    signature: signatureLine.replace(/^Signature:\s*/, ''),
    publishedBase: [
      authorityLine,
      one(/^"content-digest":/, '"content-digest" base line'),
      baseParamsLine,
    ].join('\n'),
  };
}

function readStdin() {
  return JSON.parse(readFileSync(0, 'utf8'));
}

const fromDraftFlag = process.argv.indexOf('--from-draft');
const source = fromDraftFlag >= 0 ? fromDraft(process.argv[fromDraftFlag + 1]) : readStdin();
const authority = source.authority ?? source.request?.authority;
const { body, contentDigest, signatureInput, signature } = source;

console.log(`source:    ${fromDraftFlag >= 0 ? process.argv[fromDraftFlag + 1] : 'stdin (generator JSON)'}`);
console.log(`authority: ${authority}`);
console.log(`body:      ${body}\n`);

// 1. Content-Digest, recomputed from the body bytes.
const ourDigest = `sha-256=:${createHash('sha256').update(body, 'utf8').digest('base64')}:`;
check(ourDigest === contentDigest, 'Content-Digest recomputed from the body matches the published value',
  ourDigest === contentDigest ? '' : `computed ${ourDigest}, published ${contentDigest}`);

// 2. Parse the Signature-Input dictionary member. Everything after "label=" is
//    the signature params serialization that the base's last line must carry.
const inputMatch = /^([A-Za-z0-9_-]+)=(\(([^)]*)\)(.*))$/.exec(signatureInput);
if (!inputMatch) throw new Error(`unparseable Signature-Input: ${signatureInput}`);
const [, label, sigParamsValue, componentList, paramTail] = inputMatch;

const params = {};
for (const m of paramTail.matchAll(/;([a-z]+)=("([^"]*)"|[0-9]+)/g)) {
  params[m[1]] = m[3] !== undefined ? m[3] : Number(m[2]);
}
check(params.tag === EXPECTED_TAG, `tag is "${EXPECTED_TAG}"`, `got ${JSON.stringify(params.tag)}`);
check(typeof params.created === 'number', 'created is present');
check(typeof params.expires === 'number', 'expires is present');
check(typeof params.keyid === 'string', 'keyid is present');

// 3. Rebuild the signature base from the covered component list, in list order.
const components = componentList.match(/"[^"]*"(?:;[a-z]+)*/g) ?? [];
const baseLines = components.map((component) => {
  if (component === '"@authority";req') return `"@authority";req: ${authority}`;
  if (component === '"content-digest"') return `"content-digest": ${ourDigest}`;
  throw new Error(`unexpected covered component: ${component}`);
});
check(components.length === 2, 'exactly the two components Appendix B.1 requires are covered',
  `got ${JSON.stringify(components)}`);
baseLines.push(`"@signature-params": ${sigParamsValue}`);
const base = baseLines.join('\n');

if (source.publishedBase !== undefined) {
  check(base === source.publishedBase,
    'independently rebuilt base is byte-identical to the base printed in the draft',
    base === source.publishedBase ? '' : `rebuilt:\n${base}\npublished:\n${source.publishedBase}`);
}

// 4. Select the key by independently recomputed thumbprint.
const jwks = JSON.parse(body);
const jwk = jwks.keys.find((k) => {
  const canonical = JSON.stringify({ crv: k.crv, kty: k.kty, x: k.x });
  return createHash('sha256').update(canonical).digest('base64url') === params.keyid;
});
check(Boolean(jwk), 'a key in the published body has a thumbprint equal to the signature keyid',
  `keyid ${params.keyid}`);
if (jwk) {
  check(jwk.kid === params.keyid, 'the published JWK kid equals that thumbprint',
    `kid ${jwk.kid}`);
}

// 5. Verify, with no code in common with the signer.
const sigMatch = new RegExp(`^${label}=:([^:]*):$`).exec(signature);
if (!sigMatch) throw new Error(`unparseable Signature for label ${label}: ${signature}`);
const sigBytes = Buffer.from(sigMatch[1], 'base64');
check(sigBytes.length === 64, 'signature is a 64 byte Ed25519 signature', `got ${sigBytes.length}`);

const publicKey = createPublicKey({ key: jwk, format: 'jwk' });
const ok = nodeVerify(null, Buffer.from(base, 'utf8'), publicKey, sigBytes);
check(ok, 'Ed25519 signature verifies over the independently rebuilt base');

// 6. The window a verifier would apply, per Appendix B.1: created must not be in
//    the future, expires must not have passed.
const nowArg = process.argv.indexOf('--now');
const now = nowArg >= 0 ? Number(process.argv[nowArg + 1]) : Math.floor(Date.now() / 1000);
check(params.created <= now, 'created is not in the future', `created ${params.created}, now ${now}`);
check(params.expires > now, 'expires has not passed', `expires ${params.expires}, now ${now}`);

// 7. A signature over tampered bytes must not verify. One key set swapped under a
//    captured signature is exactly what the covered content-digest prevents.
const tamperedBody = body.replace('"use":"sig"', '"use":"enc"');
const tamperedDigest = `sha-256=:${createHash('sha256').update(tamperedBody, 'utf8').digest('base64')}:`;
const tamperedBase = base.replace(ourDigest, tamperedDigest);
check(!nodeVerify(null, Buffer.from(tamperedBase, 'utf8'), publicKey, sigBytes),
  'the same signature does NOT verify over a modified body');

console.log(`\n${failures.length === 0 ? 'ALL CHECKS PASSED' : `${failures.length} CHECK(S) FAILED`}`);
process.exit(failures.length === 0 ? 0 : 1);
